// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost;

import org.eclipse.rdf4j.common.annotation.Experimental;

/** Exact RHS multiplicity kernel applied linearly to each retained outer mapping. */
@Experimental
public enum FrontierOuterKernel {
	INNER,
	EXISTS,
	NOT_EXISTS,
	MINUS,
	OPTIONAL;

	long outputMultiplicity(long rhsMultiplicity) {
		if (rhsMultiplicity < 0L) {
			throw new IllegalArgumentException("exact RHS multiplicity must be nonnegative");
		}
		return switch (this) {
		case INNER -> rhsMultiplicity;
		case EXISTS -> rhsMultiplicity == 0L ? 0L : 1L;
		case NOT_EXISTS, MINUS -> rhsMultiplicity == 0L ? 1L : 0L;
		case OPTIONAL -> Math.max(1L, rhsMultiplicity);
		};
	}

	boolean isBooleanKernel() {
		return this == EXISTS || this == NOT_EXISTS || this == MINUS;
	}
}
